<script>
	let {
		alignLeft = 'left',
		alignRight = 'left',
		left,
		right,
		children
	} = $props();

	let isRightPinned = $derived(alignRight === 'right');
	let isLeftPinned = $derived(alignLeft === 'left');
</script>

<div class="row">
{#if left}
		<div
			class="slot-wrapper left"
			class:allow-shrink={isLeftPinned}
			style:--align={alignLeft === 'right' ? 'flex-end' : 'flex-start'}
		>
			{@render left()}
		</div>
	{/if}

	{#if right}
		<div
			class="slot-wrapper right"
			class:allow-shrink={isRightPinned}
			style:--align={alignRight === 'right' ? 'flex-end' : 'flex-start'}
		>
			{@render right()}
		</div>
	{/if}

	{#if !left && !right && children}
		{@render children()}
	{/if}
</div>

<style>
	.row {
		display: flex;
		flex-wrap: wrap;
		width: 100%;
		box-sizing: border-box;

		padding: 3px 0;
	}

	.slot-wrapper :global(.inputContainer), .slot-wrapper :global(input) {
		width: 100%;
	}

	.slot-wrapper {
		box-sizing: border-box;
		display: flex;
		justify-content: var(--align);
        align-items: center;

		flex: 1 0 50%;
		min-width: 0;

		
	}

	/* Если под-контейнер всего один — забирает 100% */
	.slot-wrapper:only-child {
		flex: 1 1 100%;
	}

	.slot-wrapper.allow-shrink {
		flex-shrink: 1;
	}
</style>